// Extract order data from webhook payload
const payload = $input.first().json.body || $input.first().json;

const orderId = payload.id || ('MB-' + Math.floor(100000 + Math.random() * 900000));
const customerName = payload.customerName || 'Customer';
let phone = (payload.phone || '').replace(/[^0-9]/g, '');
if (phone.startsWith('0')) {
  phone = '92' + phone.substring(1);
}
const city = payload.city || 'Lahore';
const province = payload.province || 'Punjab';
const address = payload.address || '';
const productTitle = payload.productTitle || 'Luxury Watch';
const variant = payload.variant || 'Standard';
const quantity = payload.quantity || 1;
const totalAmount = Number(payload.totalAmount || 0);
const paymentType = payload.paymentType || 'cod';
const paymentMethod = payload.paymentMethod || (paymentType === 'cod' ? 'Cash on Delivery (COD)' : 'Online Transfer');
const transactionRef = payload.transactionRef || '';

const codAmountToCollect = paymentType === 'cod' ? totalAmount : 0;

return [{
  json: {
    orderId,
    customerName,
    phone,
    city,
    province,
    address,
    productTitle,
    variant,
    quantity,
    totalAmount,
    codAmountToCollect,
    paymentType,
    paymentMethod,
    transactionRef,
    timestamp: new Date().toISOString(),
    formattedDate: new Date().toLocaleString('en-PK', { timeZone: 'Asia/Karachi' })
  }
}];

